#include <memory>
#include <iostream>

void demonstrate_transfer() {
    std::auto_ptr<int> p1(new int(42));

    // Ownership is transferred (Destructive Copy)
    std::auto_ptr<int> p2 = p1; 

    std::cout << "P2 value: " << *p2 << "\n";

    // P1 is now NULL (it lost ownership)
    if (p1.get() == nullptr) {
        std::cout << "P1 is null after transfer.\n";
    }
    // *p1; // DANGER: Undefined behavior if accessed
}
